(() => {
  if (window.__cooFakeMic) return;
  window.__cooFakeMic = true;
  const B64 = "";
  const orig = navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices);
  navigator.mediaDevices.getUserMedia = async (constraints) => {
    try {
      const bin = atob(B64);
      const u8 = new Uint8Array(bin.length);
      for (let i=0;i<bin.length;i++) u8[i]=bin.charCodeAt(i);
      const ctx = new AudioContext({ sampleRate: 16000 });
      const buffer = await ctx.decodeAudioData(u8.buffer);
      const dest = ctx.createMediaStreamDestination();
      const src = ctx.createBufferSource();
      src.buffer = buffer; src.connect(dest);
      window.__cooTest = { ctx, src, dest, seconds: buffer.duration };
      window.__cooPlay = (delay = 0) => { try { src.start(ctx.currentTime + delay); return true; } catch(e){ console.warn('play',e&&e.message); return false; } };
      return dest.stream;
    } catch (err) { console.warn('fake mic failed', err&&err.message); return orig(constraints); }
  };
})();